const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const marovoay = ee.Geometry.Point([46.644, -16.111]).buffer(5000); // 5km buffer around Marovoay

  // 2. Data Acquisition - Sentinel-2 for specific dates
  const date1 = '2017-01-18';
  const date2 = '2020-01-27';

  // Function to get and process Sentinel-2 image
  function getWaterExtent(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(marovoay)
      .filterDate(date, ee.Date(date).advance(1, 'day'));

    const size = collection.size().getInfo();
    if (size === 0) return {count: null, pixels: null, images: 0};

    const image = collection.first();

    // Cloud masking using QA60 band
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    const maskedImage = image.updateMask(mask);

    // Calculate NDWI for water detection
    const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water pixels (NDWI > 0.1)
    const water = ndwi.gt(0.1);

    // Count water pixels
    const waterCount = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: marovoay,
      scale: 100,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    // Count total valid pixels for validation
    const pixelCount = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: marovoay,
      scale: 100,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    return {count: waterCount, pixels: pixelCount, images: size};
  }

  // Process both dates
  const result2017 = getWaterExtent(date1);
  const result2020 = getWaterExtent(date2);

  // Print evidence
  console.log(`2017-01-18: Images=${result2017.images}, WaterPixels=${result2017.count}, ValidPixels=${result2017.pixels}`);
  console.log(`2020-01-27: Images=${result2020.images}, WaterPixels=${result2020.count}, ValidPixels=${result2020.pixels}`);

  // Check for empty collections
  if (result2017.images === 0 || result2020.images === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Check for no valid pixels
  if (result2017.pixels === 0 || result2020.pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (result2017.count === null || result2020.count === null || 
      isNaN(result2017.count) || isNaN(result2020.count)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water extent and provide answer
  if (result2020.count > result2017.count) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
